def prorubric_conjunctive_score(
    gate_checks: dict[str, bool],
    violation_flags: dict[str, bool],
    secondary_scores: dict[str, float],
) -> float:
    required_gates = ['factual_correctness']
    hard_violations = ['no_factual_contradiction_or_fabrication']
    secondary_weights = {'clarity_and_structure': 0.5, 'completeness': 0.5}
    all_required_pass = all(bool(gate_checks.get(k, False)) for k in required_gates)
    no_hard_violation = not any(
        bool(violation_flags.get(k, False)) for k in hard_violations
    )
    if not (all_required_pass and no_hard_violation):
        return 0.0
    total_w = sum(secondary_weights.values()) or 1.0
    weighted = sum(
        secondary_scores.get(k, 0.0) * w for k, w in secondary_weights.items()
    )
    return max(0.0, min(1.0, weighted / total_w))
